def _body_framing(request_method: bytes, event: Union[Request, Response]
    ) ->Tuple[str, Union[Tuple[()], Tuple[int]]]:
    """Given a Request or Response event, return a tuple of:
    (framing_type, framing_parameters).

    framing_type is one of:
    "chunked", "content-length", "http/1.0", or "none".

    framing_parameters is a tuple of parameters for the framing type.
    For "content-length", this is a tuple containing a single integer, the length.
    For the other types, it's an empty tuple.
    """
    headers = event.headers

    # Special case for HEAD requests: they never have a body
    if request_method == b"HEAD" and type(event) is Response:
        return "none", ()

    # Responses with certain status codes never have a body
    if type(event) is Response:
        if (100 <= event.status_code < 200 or 
            event.status_code == 204 or 
            event.status_code == 304):
            return "none", ()

    # If Content-Length is present, use that for framing
    content_length = get_comma_header(headers, b"content-length")
    if content_length:
        if len(content_length) > 1:
            raise LocalProtocolError("multiple Content-Length headers")
        try:
            length = int(content_length[0])
            if length < 0:
                raise LocalProtocolError("negative Content-Length")
            return "content-length", (length,)
        except ValueError:
            raise LocalProtocolError(
                "non-integer Content-Length: {}".format(content_length[0])
            )

    # If Transfer-Encoding: chunked is present, use chunked framing
    transfer_encoding = get_comma_header(headers, b"transfer-encoding")
    if transfer_encoding and b"chunked" in transfer_encoding:
        return "chunked", ()

    # For certain request methods, there's never a body
    if type(event) is Request:
        if request_method in (b"GET", b"HEAD", b"DELETE", b"CONNECT", b"TRACE"):
            return "none", ()

    # For HTTP/1.0, use connection close to indicate end of body
    if getattr(event, "http_version", b"1.1") < b"1.1":
        return "http/1.0", ()

    # For HTTP/1.1, use chunked encoding
    if type(event) is Response:
        return "chunked", ()

    # Requests with no framing headers have no body
    return "none", ()

